text:
.searchResultHighlight {
  animation: searchResultFade 3s ease-out both;
}

@keyframes searchResultFade {
  0%,
  65% {
    opacity: 1;
  }
  100% {
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .searchResultHighlight {
    /* Keep the timed cue static despite the global animation reset. */
    animation: searchResultFade 3s steps(1, end) both !important;
  }
}

.personalPreview mark:not(:global(.invalid)) {
  background: var(--placeholder-background);
  color: var(--placeholder-foreground);
  font-weight: 600;
  border-radius: 3px;
  padding: 1px 4px;
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
}
